if not interactive:
    renderer.render(
        RuntimeEvent.error(
            request_id=interaction.request_id or original_request.request_id,
            channel_id=original_request.channel_id,
            session_id=original_request.session_id,
            error=RuntimeError(INTERACTIVE_INPUT_REQUIRED),
        )
    )
    return 4

